insert into public.markets (id, slug, name, about, address, city, province, postal_code, lat, lng, geofence_radius_m, website, phone, email, tags, status, featured) values
  ('00000000-0000-0000-0000-000000000001', 'st-lawrence-market', 'St. Lawrence Market', 'Toronto’s historic public market includes the South Market’s specialty food merchants, artisans and prepared-food businesses.', '91–95 Front Street East', 'Toronto', 'ON', 'M5E 1C3', 43.6486879, -79.3715454, 350, 'https://www.stlawrencemarket.com/', '416-392-7219', 'stlawrencemarket@toronto.ca', ARRAY['produce', 'bakery', 'cheese', 'meat', 'seafood', 'prepared-food', 'crafts', 'indoor', 'year-round', 'accessible'], 'published', true),
  ('00000000-0000-0000-0000-000000000002', 'evergreen-brick-works-saturday-farmers-market', 'Evergreen Brick Works Saturday Farmers Market', 'Evergreen’s year-round Saturday market connects shoppers with local Ontario farmers and food producers. It operates under the outdoor pavilions from May through October and indoors from November through April.', '550 Bayview Avenue', 'Toronto', 'ON', 'M4W 3X8', 43.6845894, -79.366016, 350, 'https://www.evergreen.ca/evergreen-brick-work/activities/saturday-farmers-market/', '416-596-7670', 'info@evergreen.ca', ARRAY['produce', 'bakery', 'meat', 'prepared-food', 'indoor', 'outdoor', 'year-round', 'parking', 'transit', 'accessible'], 'published', true),
  ('00000000-0000-0000-0000-000000000003', 'the-stops-farmers-market', 'The Stop’s Farmers’ Market', 'The Stop operates a year-round community farmers’ market with local farmers, prepared-food producers, arts and crafts, and weekly community programming.', '601 Christie Street', 'Toronto', 'ON', 'M6G 4C7', 43.6799336, -79.4241445, 220, 'https://www.thestop.org/farmersmarket/', '416-652-7867', 'farmersmarket@thestop.org', ARRAY['produce', 'meat', 'cheese', 'preserves', 'prepared-food', 'crafts', 'indoor', 'outdoor', 'year-round', 'accessible', 'card-accepted', 'atm'], 'published', true),
  ('00000000-0000-0000-0000-000000000004', 'dufferin-grove-organic-farmers-market', 'Dufferin Grove Organic Farmers’ Market', 'Established in 2002, this year-round market connects local and predominantly organic farmers and food producers with the surrounding community.', '875 Dufferin Street', 'Toronto', 'ON', 'M6H 3K8', 43.6569279, -79.433563, 220, 'https://www.dufferingrovemarket.ca/', null, 'info@dufferingrovemarket.ca', ARRAY['produce', 'organic', 'bakery', 'cheese', 'meat', 'seafood', 'honey', 'preserves', 'prepared-food', 'year-round', 'accessible'], 'published', false),
  ('00000000-0000-0000-0000-000000000005', 'sorauren-farmers-market', 'Sorauren Farmers’ Market', 'This nonprofit farmers’ market has connected the community with sustainable farmers and local food producers since 2008. This record represents the Sorauren Avenue Park floor.', '50 Wabash Avenue', 'Toronto', 'ON', 'M6R 1N2', 43.6480468, -79.4430797, 220, 'https://www.soraurenmarket.com/', null, null, ARRAY['produce', 'organic', 'bakery', 'cheese', 'meat', 'seafood', 'flowers', 'honey', 'preserves', 'prepared-food', 'outdoor', 'year-round', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000006', 'the-leslieville-farmers-market', 'The Leslieville Farmers’ Market', 'The Leslieville Farmers’ Market’s Greenwood Park edition is a weekly outdoor market for local food, sustainable agriculture, small-scale producers and handmade goods.', '150 Greenwood Avenue', 'Toronto', 'ON', 'M4L 1Y5', 43.668448, -79.3292284, 220, 'https://www.leslievillemarket.com/', '647-381-4555', 'alexa@leslievillemarket.com', ARRAY['produce', 'bakery', 'honey', 'preserves', 'prepared-food', 'coffee', 'crafts', 'outdoor', 'parking', 'transit', 'accessible', 'card-accepted', 'family-friendly', 'seasonal'], 'published', false),
  ('00000000-0000-0000-0000-000000000007', 'withrow-park-farmers-market', 'Withrow Park Farmers’ Market', 'This nonprofit seasonal market connects local residents with Ontario farmers, food producers and small businesses in the northeast corner of Withrow Park.', '725 Logan Avenue', 'Toronto', 'ON', 'M4K 3B9', 43.6763536, -79.3474728, 220, 'https://withrowmarket.ca/', '647-852-9275', 'manager@withrowmarket.ca', ARRAY['produce', 'bakery', 'meat', 'flowers', 'prepared-food', 'outdoor', 'seasonal', 'accessible', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000008', 'trinity-bellwoods-farmers-market', 'Trinity Bellwoods Farmers’ Market', 'A farmer-focused market supporting access to local, sustainable, naturally grown and certified organic agriculture. It operates seasonally in the northwest section of Trinity Bellwoods Park.', '1053 Dundas Street West', 'Toronto', 'ON', 'M6J 1X1', 43.6492554, -79.4175195, 220, 'https://www.tbfm.ca/', null, 'hello@tbfm.ca', ARRAY['produce', 'organic', 'prepared-food', 'outdoor', 'seasonal', 'transit', 'accessible', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000009', 'the-junction-farmers-market', 'The Junction Farmers Market', 'An independent nonprofit market providing sustainably produced fresh food while supporting local growers, producers and community food access.', '275 Keele Street', 'Toronto', 'ON', 'M6P 2K5', 43.6622321, -79.4625, 220, 'https://junctionmarket.ca/', null, 'info@junctionmarket.ca', ARRAY['produce', 'organic', 'bakery', 'cheese', 'meat', 'flowers', 'honey', 'prepared-food', 'coffee', 'crafts', 'outdoor', 'seasonal', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000010', 'st-lawrence-farmers-market', 'St. Lawrence Farmers’ Market', 'The historic weekly farmers’ market operates inside St. Lawrence Market North. The market has operated in the St. Lawrence neighbourhood since 1803.', '92 Front Street East', 'Toronto', 'ON', 'M5E 1C3', 43.6495154, -79.3719386, 350, 'https://www.stlawrencemarket.com/', '416-392-7219', 'stlawrencemarket@toronto.ca', ARRAY['produce', 'organic', 'bakery', 'cheese', 'meat', 'seafood', 'flowers', 'honey', 'preserves', 'prepared-food', 'coffee', 'indoor', 'year-round', 'parking', 'transit', 'accessible'], 'published', false),
  ('00000000-0000-0000-0000-000000000011', 'underpass-park-farmers-market', 'Underpass Park Farmers’ Market', 'A seasonal, nonprofit community farmers’ market operating in Underpass Park. Its current offerings include produce, baked goods and prepared food.', '29 Lower River Street', 'Toronto', 'ON', null, 43.6555674, -79.3549712, 220, 'https://underpassparkmarket.com/', null, 'manager.upfm@gmail.com', ARRAY['produce', 'bakery', 'prepared-food', 'outdoor', 'seasonal', 'card-accepted'], 'published', false),
  ('00000000-0000-0000-0000-000000000012', 'east-lynn-park-farmers-market', 'East Lynn Park Farmers’ Market', 'A Verified Local Market operated jointly by Farmers’ Markets Ontario and Danforth East Community Association volunteers. Farmers sell what they grow, supplemented by specialty food and drink vendors.', '1949 Danforth Avenue', 'Toronto', 'ON', 'M4C 1J4', 43.6841988, -79.315742, 220, 'https://www.eastlynnparkfarmersmarket.ca/', '613-475-4769', 'teamfmo@farmersmarketsontario.com', ARRAY['produce', 'bakery', 'cheese', 'meat', 'seafood', 'honey', 'prepared-food', 'outdoor', 'seasonal', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000013', 'allan-gardens-farmers-market', 'Allan Gardens Farmers’ Market', 'A year-round market connecting local farmers, food producers and artisan makers directly with consumers. It is operated by the nonprofit Friends of Allan Gardens at the Children’s Conservatory and Teaching Garden.', '19 Horticultural Avenue', 'Toronto', 'ON', null, 43.6619028, -79.3754708, 220, 'https://www.friendsofallangardens.ca/saturday-farmers-market', null, 'info@friendsofallangardens.ca', ARRAY['produce', 'bakery', 'meat', 'seafood', 'flowers', 'honey', 'prepared-food', 'crafts', 'indoor', 'outdoor', 'year-round', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000014', 'cabbagetown-farmers-market', 'Cabbagetown Farmers’ Market', 'A seasonal park market bringing together more than 30 southern Ontario vendors selling produce, artisan goods and street food. It operates in Riverdale Park West outside the gates of Riverdale Farm.', '191 Winchester Street', 'Toronto', 'ON', 'M4X 1V4', 43.66695, -79.36271, 220, 'https://www.cabbagetownmarket.ca/', null, 'info@cabbagetownmarket.ca', ARRAY['produce', 'organic', 'bakery', 'cheese', 'seafood', 'honey', 'prepared-food', 'crafts', 'outdoor', 'seasonal', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000015', 'east-york-farmers-market', 'East York Farmers’ Market', 'A seasonal market at the East York Civic Centre offering Ontario produce, honey, preserves, smoked meats, cheese, baking and other locally made products.', '850 Coxwell Avenue', 'Toronto', 'ON', 'M4C 5R1', 43.6916609, -79.3286438, 250, 'https://www.facebook.com/EastYorkFarmersMarket/', '519-955-1434', 'eastyorkmarket26@gmail.com', ARRAY['produce', 'bakery', 'cheese', 'meat', 'honey', 'preserves', 'prepared-food', 'crafts', 'outdoor', 'seasonal'], 'published', false),
  ('00000000-0000-0000-0000-000000000016', 'eglinton-way-bia-farmers-market', 'Eglinton Way BIA Farmers’ Market', 'A weekly community market supporting local farms, businesses and food security. It features fresh goods, prepared food, handmade crafts, live music and children’s activities.', '125 Burnaby Boulevard', 'Toronto', 'ON', null, 43.7043176, -79.4126572, 220, 'https://www.theeglintonway.com/farmersmarket', '647-376-3294', 'farmersmarket@theeglintonway.com', ARRAY['produce', 'prepared-food', 'crafts', 'outdoor', 'seasonal', 'parking', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000017', 'humber-bay-shores-farmers-market', 'Humber Bay Shores Farmers Market', 'A seasonal waterfront market organized by the Humber Bay Shores Condominium Association. Ontario farmers and producers offer produce, meat, cheese, flowers, preserves, baking and prepared food.', '2195 Lake Shore Boulevard West', 'Toronto', 'ON', 'M8V 3X7', 43.6202314, -79.4809687, 250, 'https://hbsca.ca/events/humber-bay-shores-farmers-market/', null, 'zweingarten@gmail.com', ARRAY['produce', 'organic', 'bakery', 'cheese', 'meat', 'flowers', 'honey', 'preserves', 'prepared-food', 'coffee', 'outdoor', 'seasonal', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000018', 'scarborough-farmers-market', 'Scarborough Farmers’ Market', 'A seasonal market providing affordable, culturally appropriate Ontario produce and artisan products. It operates in Cynthia Lai Park, formerly known as Rosebank Park.', '1051 Progress Avenue', 'Toronto', 'ON', 'M1B 5Z6', 43.7929706, -79.2334845, 220, 'https://www.scarboroughfarmersmarket.ca/', null, 'scarboroughfarmersmarket@gmail.com', ARRAY['produce', 'prepared-food', 'crafts', 'outdoor', 'seasonal', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000019', 'north-york-farmers-market', 'North York Farmers’ Market', 'A longstanding seasonal market bringing Ontario produce and farm products to Willowdale. Products include fruits, vegetables, honey, flowers, baking, cheese and cured meat.', '5100 Yonge Street', 'Toronto', 'ON', 'M2N 5V7', 43.7679485, -79.4132948, 250, 'https://northyorkfarmersmarket.ca/', null, 'info@northyorkfarmersmarket.ca', ARRAY['produce', 'bakery', 'cheese', 'meat', 'flowers', 'honey', 'preserves', 'outdoor', 'seasonal', 'transit', 'accessible'], 'published', false),
  ('00000000-0000-0000-0000-000000000020', 'sickkids-market', 'SickKids Market', 'An Appletree market serving hospital families, staff and the surrounding neighbourhood with farm-fresh products and lunchtime options. This record represents the weekly outdoor market on the hospital’s University Avenue front driveway.', '555 University Avenue', 'Toronto', 'ON', 'M5G 1X8', 43.6569299, -79.3873858, 250, 'https://www.appletreemarkets.ca/markets', '416-899-1990', null, ARRAY['produce', 'bakery', 'cheese', 'honey', 'prepared-food', 'outdoor', 'seasonal', 'transit', 'accessible', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000021', 'davisville-village-market', 'Davisville Village Market', 'A weekly Appletree community market in June Rowlands Park featuring rural farmers, local producers, artisans and prepared foods. The market operates outdoors on Tuesday afternoons.', '220 Davisville Avenue', 'Toronto', 'ON', null, 43.70012, -79.3892438, 220, 'https://www.appletreemarkets.ca/markets', '416-899-1990', null, ARRAY['produce', 'prepared-food', 'crafts', 'outdoor', 'seasonal', 'transit', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000022', 'bloor-borden-farmers-market', 'Bloor.Borden Farmers’ Market', 'A volunteer-run, Farmers’ Markets Ontario partner market offering local produce, meat, dairy, seafood, baked goods and prepared foods. It operates rain or shine in the Green P lot south of Bloor Street.', '300 Borden Street', 'Toronto', 'ON', 'M5S 2N5', 43.6650982, -79.4087268, 180, 'https://bloorborden.com/', '613-475-4769', 'bloorbordenmarket@gmail.com', ARRAY['produce', 'organic', 'bakery', 'cheese', 'meat', 'seafood', 'honey', 'preserves', 'prepared-food', 'outdoor', 'seasonal', 'parking', 'transit', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000023', 'annette-village-farmers-market', 'Annette Village Farmers’ Market', 'A weekly neighbourhood market bringing together local farmers, food producers, artists, crafters and makers. It includes live music, children’s activities and seasonal community events.', '680 Annette Street', 'Toronto', 'ON', 'M6S 2C5', 43.6591747, -79.4848367, 180, 'https://www.annettevillagemarket.com/', null, 'annettevillagefarmersmrkt@gmail.com', ARRAY['produce', 'organic', 'bakery', 'cheese', 'meat', 'flowers', 'honey', 'preserves', 'prepared-food', 'coffee', 'crafts', 'outdoor', 'seasonal', 'parking', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000024', 'montgomerys-inn-farmers-market', 'Montgomery’s Inn Farmers’ Market', 'A City of Toronto market connecting Montgomery’s Inn’s agricultural history with local farmers and small food producers. Offerings include seasonal produce, baked goods, prepared foods and bread baked in the Inn’s wood-burning oven.', '4709 Dundas Street West', 'Toronto', 'ON', 'M9A 1A8', 43.6517556, -79.5257514, 220, 'https://www.toronto.ca/explore-enjoy/history-art-culture/museums/montgomerys-inn/?accordion=farmers-market', '416-394-8113', 'montinn@toronto.ca', ARRAY['produce', 'bakery', 'prepared-food', 'indoor', 'outdoor', 'year-round', 'parking', 'transit', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000025', 'weston-village-farmers-market', 'Weston Village Farmers’ Market', 'A long-running community market operated by the Weston Village BIA. Its 2026 season features local produce, prepared foods, artisan goods, entertainment and free children’s activities.', '34 John Street', 'Toronto', 'ON', 'M9N 0B2', 43.7020223, -79.5174008, 220, 'https://westonvillagebia.com/', '416-249-0691', 'admin@westonvillagebia.com', ARRAY['produce', 'prepared-food', 'crafts', 'outdoor', 'seasonal', 'transit', 'accessible', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000026', 'flemo-farmers-market', 'Flemo Farmers’ Market', 'A weekly market at Flemo Farm selling culturally diverse produce grown by Flemingdon Park community farmers. Local residents and organizations may also offer prepared food, crafts and community activities.', '150 Grenoble Drive', 'Toronto', 'ON', 'M3C 1B9', 43.7135431, -79.3264436, 220, 'https://flemofarm.ca/', '416-230-6984', 'flemofarm@gmail.com', ARRAY['produce', 'prepared-food', 'crafts', 'outdoor', 'seasonal', 'transit', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000027', 'malvern-urban-farm-farmers-market', 'Malvern Urban Farm Farmers Market', 'A weekly public market organized by Malvern Family Resource Centre. Community farmers sell produce grown at Malvern Urban Farm, alongside baked goods, beverages, hot food and other local vendors.', '90 Littles Road', 'Toronto', 'ON', 'M1B 5E2', 43.818474, -79.2054483, 220, 'https://www.mfrc.org/urban-agriculture-and-food-programs', '416-284-4184 ext. 221', 'cperttula@mfrc.org', ARRAY['produce', 'prepared-food', 'crafts', 'outdoor', 'seasonal', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000028', 'courtyard-farmers-market', 'Courtyard Farmers’ Market', 'A weekly neighbourhood market offering Ontario-grown produce, culturally appropriate foods and artisanal products in Robertson Parkette.', '1549 Danforth Avenue', 'Toronto', 'ON', 'M4J 1N8', 43.6830539, -79.3240825, 200, 'https://www.courtyardfarmersmkt.ca/', '647-835-4064', 'jmforde709@gmail.com', ARRAY['produce', 'bakery', 'preserves', 'prepared-food', 'crafts', 'outdoor', 'seasonal', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000029', 'afro-caribbean-farmers-market', 'Afro-Caribbean Farmers’ Market', 'This culturally specific market connects Black farmers, growers and food businesses with the Little Jamaica community. Its offerings include culturally appropriate produce, baked goods, bread, juices, preserves, sauces and artisan products.', '1815 Eglinton Avenue West', 'Toronto', 'ON', 'M6E 2H6', 43.69558, -79.449921, 220, 'https://afrocaribbeanfarmersmarket.com/', null, null, ARRAY['produce', 'bakery', 'preserves', 'prepared-food', 'crafts', 'outdoor', 'seasonal', 'transit', 'accessible', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000030', 'etobicoke-civic-centre-farmers-market', 'Etobicoke Civic Centre Farmers’ Market', 'A longstanding seasonal market held in the front parking area of Etobicoke Civic Centre. Current listings describe Ontario produce alongside baked goods, cheese, flowers and crafts.', '399 The West Mall', 'Toronto', 'ON', 'M9C 2Y2', 43.64373, -79.56638, 300, 'https://www.toronto.ca/services-payments/venues-facilities-bookings/booking-city-facilities/civic-centres/', null, null, ARRAY['produce', 'bakery', 'cheese', 'flowers', 'crafts', 'outdoor', 'seasonal', 'parking', 'accessible', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000031', 'yum-market', 'YUM! Market', 'Regenesis operates this weekly York University market to improve access to fresh, locally sourced food and sustainable products.', '88 The Pond Road', 'Toronto', 'ON', 'M3J 2S5', 43.7718935, -79.5012108, 180, 'https://regenesis.eco/en/yumarket', null, null, ARRAY['produce', 'organic', 'prepared-food', 'crafts', 'indoor', 'transit', 'accessible'], 'published', false)
