insert into public.vendors (id, slug, name, about, website, phone, tags, status) values
  ('00000000-0000-0000-0000-000000000101', 'red-barn-roots', 'Red Barn Roots', 'Certified organic vegetables from a 40-acre plot north of Toronto. CSA boxes and Saturday stall.', 'https://example.com/red-barn-roots', '905-555-0142', ARRAY['produce', 'organic'], 'published'),
  ('00000000-0000-0000-0000-000000000102', 'maple-hearth-bakery', 'Maple Hearth Bakery', 'Naturally leavened breads and butter pastries. Ontario wheat, baked overnight.', null, '416-555-0198', ARRAY['bakery'], 'published'),
  ('00000000-0000-0000-0000-000000000103', 'loon-lake-honey', 'Loon Lake Honey', 'Small-lot honey from hives on the Canadian Shield. Wildflower, basswood, and a spring dandelion run.', null, null, ARRAY['honey'], 'published'),
  ('00000000-0000-0000-0000-000000000104', 'twin-river-dairy', 'Twin River Dairy', 'Raw-milk style cheeses made from a closed herd in Oxford County. Clothbound cheddar and a weekly fresh chèvre.', 'https://example.com/twin-river', '519-555-0110', ARRAY['cheese'], 'published'),
  ('00000000-0000-0000-0000-000000000105', 'shoreline-smokehouse', 'Shoreline Smokehouse', 'Hot-smoked Great Lakes trout and a peppery summer sausage. Cooler packed, card accepted.', null, '647-555-0166', ARRAY['seafood', 'meat'], 'published')
